namespace sv_4bf9a74c2d73408a915b192831924eaa;

public record TaskItem(int Id, string Title, string Assignee, string Priority, DateTime DueDate, string Status);

public interface ITaskService
{
    Task<List<TaskItem>> GetAllTasksAsync();
    Task<TaskItem> CreateTaskAsync(string title, string assignee, string priority, DateTime dueDate);
    Task UpdateTaskStatusAsync(int taskId, string newStatus);
}

.board-stats-bar {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
    margin-bottom: 1rem;
}

.stat-item {
    display: flex;
    flex-direction: column;
    align-items: center;
}

.stat-label {
    font-size: 0.75rem;
    text-transform: uppercase;
    color: #6c757d;
}

.stat-value {
    font-size: 1.5rem;
    font-weight: bold;
}

.stat-overdue .stat-value {
    color: #dc3545;
}

.board-search-bar {
    margin-bottom: 1rem;
}

.board-search-bar input {
    width: 100%;
    padding: 0.5rem 1rem;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    font-size: 1rem;
}

.kanban-board {
    display: flex;
    gap: 1rem;
    align-items: flex-start;
}

.kanban-column {
    flex: 1;
    background: #f1f3f5;
    border-radius: 8px;
    padding: 1rem;
    min-height: 400px;
    display: flex;
    flex-direction: column;
}

.column-header h3 {
    margin: 0 0 0.75rem 0;
    font-size: 1.1rem;
}

.task-count {
    color: #6c757d;
    font-weight: normal;
}

.column-body {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.column-footer {
    margin-top: 0.75rem;
}

.task-card {
    background: #ffffff;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 0.75rem;
}

.task-title {
    margin: 0 0 0.25rem 0;
    font-size: 0.95rem;
}

.task-assignee {
    margin: 0 0 0.5rem 0;
    font-size: 0.85rem;
    color: #6c757d;
}

.priority-badge {
    display: inline-block;
    padding: 0.15rem 0.5rem;
    border-radius: 4px;
    font-size: 0.75rem;
    font-weight: 600;
    margin-right: 0.5rem;
}

.priority-high {
    background: #f8d7da;
    color: #842029;
}

.priority-medium {
    background: #fff3cd;
    color: #664d03;
}

.priority-low {
    background: #d1e7dd;
    color: #0f5132;
}

.task-due-date {
    font-size: 0.8rem;
    color: #6c757d;
}

.task-actions {
    margin-top: 0.5rem;
    display: flex;
    gap: 0.5rem;
}

.btn-move {
    font-size: 0.75rem;
    padding: 0.25rem 0.5rem;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    background: #ffffff;
    cursor: pointer;
}

.btn-move:hover {
    background: #e9ecef;
}

.btn-add-task {
    width: 100%;
    padding: 0.5rem;
    border: 1px dashed #adb5bd;
    border-radius: 6px;
    background: transparent;
    cursor: pointer;
    color: #6c757d;
}

.btn-add-task:hover {
    background: #e9ecef;
}

.add-task-form {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    background: #ffffff;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 0.75rem;
}

.add-task-form input,
.add-task-form select {
    padding: 0.4rem 0.5rem;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    font-size: 0.9rem;
}

.form-actions {
    display: flex;
    gap: 0.5rem;
}

.btn-save {
    padding: 0.4rem 1rem;
    background: #0d6efd;
    color: #ffffff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.btn-cancel {
    padding: 0.4rem 1rem;
    background: #6c757d;
    color: #ffffff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.loading-message {
    text-align: center;
    color: #6c757d;
    padding: 2rem;
}

.error-message {
    background: #f8d7da;
    color: #842029;
    padding: 1rem;
    border-radius: 6px;
    margin-bottom: 1rem;
}

.error-message button {
    margin-top: 0.5rem;
    padding: 0.4rem 1rem;
    background: #dc3545;
    color: #ffffff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

