+.task-count {
+    color: #6c757d;
+    font-weight: normal;
+}
+
+.column-body {
+    flex: 1;
+    display: flex;
+    flex-direction: column;
+    gap: 0.5rem;
+}
+
+.column-footer {
+    margin-top: 0.75rem;
+}
+
+.task-card {
+    background: #ffffff;
+    border: 1px solid #dee2e6;
+    border-radius: 6px;
+    padding: 0.75rem;
+}
+
+.task-title {
+    margin: 0 0 0.25rem 0;
+    font-size: 0.95rem;
+}
+
+.task-assignee {
+    margin: 0 0 0.5rem 0;
+    font-size: 0.85rem;
+    color: #6c757d;
+}
+
+.priority-badge {
+    display: inline-block;
+    padding: 0.15rem 0.5rem;
