+    font-size: 0.75rem;
+    font-weight: 600;
+    margin-right: 0.5rem;
+}
+
+.priority-high {
+    background: #f8d7da;
+    color: #842029;
+}
+
+.priority-medium {
+    background: #fff3cd;
+    color: #664d03;
+}
+
+.priority-low {
+    background: #d1e7dd;
+    color: #0f5132;
+}
+
+.task-due-date {
+    font-size: 0.8rem;
+    color: #6c757d;
+}
+
+.task-actions {
+    margin-top: 0.5rem;
+    display: flex;
+    gap: 0.5rem;
+}
+
+.btn-move {
+    font-size: 0.75rem;
+    padding: 0.25rem 0.5rem;
+    border: 1px solid #dee2e6;
+    border-radius: 4px;
+    background: #ffffff;
+    cursor: pointer;
+}
+
+.btn-move:hover {
+    background: #e9ecef;
+}
+
+.btn-add-task {
+    width: 100%;
+    padding: 0.5rem;
+    border: 1px dashed #adb5bd;
+    border-radius: 6px;
+    background: transparent;
+    cursor: pointer;
+    color: #6c757d;
+}
+
+.btn-add-task:hover {
+    background: #e9ecef;
+}
+
+.add-task-form {
+    display: flex;
+    flex-direction: column;
