+    border: 1px solid #dee2e6;
+    border-radius: 6px;
+    padding: 0.75rem;
+}
+
+.add-task-form input,
+.add-task-form select {
+    padding: 0.4rem 0.5rem;
+    border: 1px solid #dee2e6;
+    border-radius: 4px;
+    font-size: 0.9rem;
+}
+
+.form-actions {
+    display: flex;
+    gap: 0.5rem;
+}
+
+.btn-save {
+    padding: 0.4rem 1rem;
+    background: #0d6efd;
+    color: #ffffff;
+    border: none;
+    border-radius: 4px;
+    cursor: pointer;
+}
+
+.btn-cancel {
+    padding: 0.4rem 1rem;
+    background: #6c757d;
+    color: #ffffff;
+    border: none;
+    border-radius: 4px;
+    cursor: pointer;
+}
+
+.loading-message {
+    text-align: center;
+    color: #6c757d;
+    padding: 2rem;
+}
+
+.error-message {
+    background: #f8d7da;
+    color: #842029;
+    padding: 1rem;
+    border-radius: 6px;
+    margin-bottom: 1rem;
+}
+
+.error-message button {
+    margin-top: 0.5rem;
+    padding: 0.4rem 1rem;
+    background: #dc3545;
+    color: #ffffff;
+    border: none;
+    border-radius: 4px;
+    cursor: pointer;
+}
